<?php
namespace Tests\Feature;
use App\Models\InventoryItem;use App\Models\Product;use App\Models\Role;use App\Models\User;use Database\Seeders\RbacSeeder;use Illuminate\Foundation\Testing\RefreshDatabase;use Tests\TestCase;
final class InventoryApiTest extends TestCase{use RefreshDatabase;private Product $product;protected function setUp():void{parent::setUp();$this->seed(RbacSeeder::class);$this->product=Product::query()->create(['name'=>'Stock Product','slug'=>'stock-product','type'=>'simple','status'=>'active']);}public function test_inventory_requires_authentication_and_permission():void{$this->getJson('/api/v1/inventory')->assertUnauthorized();$customer=$this->userWithRole('customer');$this->actingAs($customer)->getJson('/api/v1/inventory')->assertForbidden();}public function test_product_manager_can_adjust_stock_and_movement_is_recorded():void{$manager=$this->userWithRole('product_manager');$this->actingAs($manager)->postJson('/api/v1/inventory/adjust',['product_id'=>$this->product->id,'quantity'=>10,'reason'=>'purchase','note'=>'Initial stock'])->assertOk()->assertJsonPath('data.on_hand',10)->assertJsonPath('data.available',10);$item=InventoryItem::query()->firstOrFail();$this->assertDatabaseHas('inventory_movements',['inventory_item_id'=>$item->id,'actor_id'=>$manager->id,'quantity'=>10,'on_hand_after'=>10,'reason'=>'purchase']);}public function test_stock_cannot_go_below_reserved_and_reservation_lifecycle_is_safe():void{$manager=$this->userWithRole('product_manager');$this->actingAs($manager)->postJson('/api/v1/inventory/adjust',['product_id'=>$this->product->id,'quantity'=>5,'reason'=>'purchase'])->assertOk();$this->actingAs($manager)->postJson('/api/v1/inventory/reserve',['product_id'=>$this->product->id,'quantity'=>3])->assertOk()->assertJsonPath('data.reserved',3)->assertJsonPath('data.available',2);$this->actingAs($manager)->postJson('/api/v1/inventory/adjust',['product_id'=>$this->product->id,'quantity'=>-3,'reason'=>'loss'])->assertUnprocessable();$this->actingAs($manager)->postJson('/api/v1/inventory/release',['product_id'=>$this->product->id,'quantity'=>3])->assertOk()->assertJsonPath('data.reserved',0);$this->actingAs($manager)->postJson('/api/v1/inventory/adjust',['product_id'=>$this->product->id,'quantity'=>-5,'reason'=>'sale'])->assertOk()->assertJsonPath('data.on_hand',0);}public function test_invalid_adjustment_and_variant_mismatch_are_rejected():void{$manager=$this->userWithRole('product_manager');$this->actingAs($manager)->postJson('/api/v1/inventory/adjust',['product_id'=>$this->product->id,'quantity'=>0,'reason'=>'bad'])->assertUnprocessable();$other=Product::query()->create(['name'=>'Other','slug'=>'other','type'=>'simple','status'=>'active']);$variant=$other->variants()->create(['sku'=>'INV-SKU','price'=>100,'status'=>'active','combination_hash'=>hash('sha256','inv')]);$this->actingAs($manager)->postJson('/api/v1/inventory/adjust',['product_id'=>$this->product->id,'variant_id'=>$variant->id,'quantity'=>1,'reason'=>'purchase'])->assertNotFound();}private function userWithRole(string $role):User{$user=User::factory()->create();$user->roles()->attach(Role::query()->where('slug',$role)->firstOrFail());return $user;}}
